import { runMigrations } from '@projexlight/migration-runner';
import { migrationsDir, syncCatalog } from '@projexlight/sdk-catalog-index';
await runMigrations([{ sdk: 'sdk-catalog-index', dir: migrationsDir }]);
const summary = await syncCatalog({ repoRoot: process.env.PROJEXCLOUD_REPO_ROOT });
console.log(`catalog v${summary.version}: ${summary.changed} changed`);

import { embed, searchCatalog } from '@projexlight/sdk-catalog-index';
const qv = await embed('financial accounting system');
const hits = await searchCatalog(qv, 12);
// hits: [{ sdk_name, score }] — best score per SDK

import { searchCatalog, getIngestTargets, embed } from '@projexlight/sdk-catalog-index';
const qv = await embed('import customer records');
const hits = await searchCatalog(qv, 5, { kind: 'ingest' });
const targets = await getIngestTargets('customer'); // endpoints + payload schema
